# Cleanup script for GeLB repository
# Removes Python bytecode, pytest cache, and ANTLR4 generated files

$ErrorActionPreference = "Stop"

# Get the root directory (parent of scripts directory)
$rootDir = Split-Path -Parent $PSScriptRoot

Write-Host "Cleaning up GeLB repository..."

# Remove directories containing Python auto-generated bytecode
Write-Host "Removing Python bytecode..."
Get-ChildItem -Path $rootDir -Recurse -Directory -Filter "__pycache__" | 
    ForEach-Object { Remove-Item -Path $_.FullName -Recurse -Force }

# Remove pytest cache directory
Write-Host "Removing pytest cache..."
$pytestCache = Join-Path $rootDir ".pytest_cache"
if (Test-Path $pytestCache) {
    Remove-Item -Path $pytestCache -Recurse -Force
}

# Remove files auto-generated by ANTLR4
Write-Host "Removing ANTLR4 generated files..."
$antlrDir = Join-Path $rootDir "gelb\antlr_part\generated_code"
if (Test-Path $antlrDir) {
    Get-ChildItem -Path $antlrDir -Filter "*.interp" | Remove-Item -Force
    Get-ChildItem -Path $antlrDir -Filter "*.tokens" | Remove-Item -Force
    Get-ChildItem -Path $antlrDir -Filter "GeLBLexer.py" | Remove-Item -Force
    Get-ChildItem -Path $antlrDir -Filter "GeLBParser.py" | Remove-Item -Force
    Get-ChildItem -Path $antlrDir -Filter "GeLBVisitor.py" | Remove-Item -Force
}

# Remove ANTLR grammar cache
Write-Host "Removing ANTLR grammar cache..."
$antlrCache = Join-Path $rootDir ".antlr"
if (Test-Path $antlrCache) {
    Remove-Item -Path $antlrCache -Recurse -Force
}

# Remove Python package build artifacts
Write-Host "Removing Python package build artifacts..."
$eggInfo = Get-ChildItem -Path $rootDir -Directory -Filter "*.egg-info"
if ($eggInfo) {
    Remove-Item -Path $eggInfo.FullName -Recurse -Force
}
$dist = Join-Path $rootDir "dist"
if (Test-Path $dist) {
    Remove-Item -Path $dist -Recurse -Force
}
$build = Join-Path $rootDir "build"
if (Test-Path $build) {
    Remove-Item -Path $build -Recurse -Force
}

Write-Host "Repository cleanup complete!"
